-- Server-sent text. is_reviewed stays 0 until a native speaker has checked it (see LOCALIZATION_GUIDE.md).
INSERT INTO translations (namespace, translation_key, language_code, value, is_reviewed)
SELECT 'errors', k.code, k.lang, k.msg, 0 FROM (
  SELECT 'NOT_FOUND' code, 'en' lang, 'Not found.' msg UNION ALL SELECT 'NOT_FOUND','hi','नहीं मिला।' UNION ALL SELECT 'NOT_FOUND','mr','सापडले नाही.' UNION ALL SELECT 'NOT_FOUND','es','No encontrado.' UNION ALL SELECT 'NOT_FOUND','fr','Introuvable.' UNION ALL SELECT 'NOT_FOUND','de','Nicht gefunden.' UNION ALL SELECT 'NOT_FOUND','ar','غير موجود.' UNION ALL SELECT 'NOT_FOUND','pt','Não encontrado.' UNION ALL SELECT 'NOT_FOUND','ja','見つかりません。'
  UNION ALL SELECT 'FORBIDDEN','en','You do not have permission to do this.' UNION ALL SELECT 'FORBIDDEN','hi','आपको यह करने की अनुमति नहीं है।' UNION ALL SELECT 'FORBIDDEN','mr','तुम्हाला हे करण्याची परवानगी नाही.' UNION ALL SELECT 'FORBIDDEN','es','No tienes permiso para hacer esto.' UNION ALL SELECT 'FORBIDDEN','fr','Vous n''avez pas l''autorisation.' UNION ALL SELECT 'FORBIDDEN','de','Dazu fehlt dir die Berechtigung.' UNION ALL SELECT 'FORBIDDEN','ar','ليس لديك إذن للقيام بذلك.' UNION ALL SELECT 'FORBIDDEN','pt','Não tem permissão para fazer isto.' UNION ALL SELECT 'FORBIDDEN','ja','この操作を行う権限がありません。'
  UNION ALL SELECT 'VALIDATION_FAILED','en','Some fields are invalid.' UNION ALL SELECT 'VALIDATION_FAILED','hi','कुछ फ़ील्ड अमान्य हैं।' UNION ALL SELECT 'VALIDATION_FAILED','mr','काही फील्ड अवैध आहेत.' UNION ALL SELECT 'VALIDATION_FAILED','es','Algunos campos no son válidos.' UNION ALL SELECT 'VALIDATION_FAILED','fr','Certains champs ne sont pas valides.' UNION ALL SELECT 'VALIDATION_FAILED','de','Einige Felder sind ungültig.' UNION ALL SELECT 'VALIDATION_FAILED','ar','بعض الحقول غير صالحة.' UNION ALL SELECT 'VALIDATION_FAILED','pt','Alguns campos são inválidos.' UNION ALL SELECT 'VALIDATION_FAILED','ja','無効な項目があります。'
  UNION ALL SELECT 'ORDER_NOT_PAID','en','This order has not been paid yet.' UNION ALL SELECT 'ORDER_NOT_PAID','hi','इस ऑर्डर का भुगतान अभी नहीं हुआ है।' UNION ALL SELECT 'ORDER_NOT_PAID','mr','या ऑर्डरचे पैसे अद्याप दिलेले नाहीत.' UNION ALL SELECT 'ORDER_NOT_PAID','es','Este pedido aún no se ha pagado.' UNION ALL SELECT 'ORDER_NOT_PAID','fr','Cette commande n''est pas encore payée.' UNION ALL SELECT 'ORDER_NOT_PAID','de','Diese Bestellung ist noch nicht bezahlt.' UNION ALL SELECT 'ORDER_NOT_PAID','ar','لم يتم دفع هذا الطلب بعد.' UNION ALL SELECT 'ORDER_NOT_PAID','pt','Este pedido ainda não foi pago.' UNION ALL SELECT 'ORDER_NOT_PAID','ja','この注文はまだ支払われていません。'
  UNION ALL SELECT 'PRODUCT_UNAVAILABLE','en','This item is not available right now.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','hi','यह आइटम अभी उपलब्ध नहीं है।' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','mr','ही वस्तू सध्या उपलब्ध नाही.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','es','Este artículo no está disponible ahora.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','fr','Cet article n''est pas disponible pour le moment.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','de','Dieser Artikel ist gerade nicht verfügbar.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','ar','هذا الصنف غير متوفر حاليًا.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','pt','Este artigo não está disponível agora.' UNION ALL SELECT 'PRODUCT_UNAVAILABLE','ja','この商品は現在ご利用いただけません。'
) k
ON DUPLICATE KEY UPDATE value = VALUES(value);

INSERT INTO notification_templates (template_key, channel) VALUES ('order_ready', 'in_app'), ('order_ready', 'push') AS new ON DUPLICATE KEY UPDATE is_active = 1;

INSERT INTO notification_template_translations (template_id, language_code, title, body, is_reviewed)
SELECT t.id, x.lang, x.title, x.body, 0 FROM notification_templates t JOIN (
  SELECT 'en' lang, 'Your order is ready' title, 'Order #{number} is ready.' body UNION ALL SELECT 'hi','आपका ऑर्डर तैयार है','ऑर्डर #{number} तैयार है।' UNION ALL SELECT 'mr','तुमची ऑर्डर तयार आहे','ऑर्डर #{number} तयार आहे.' UNION ALL SELECT 'es','Tu pedido está listo','El pedido #{number} está listo.' UNION ALL SELECT 'fr','Votre commande est prête','La commande n° {number} est prête.' UNION ALL SELECT 'de','Deine Bestellung ist fertig','Bestellung #{number} ist fertig.' UNION ALL SELECT 'ar','طلبك جاهز','الطلب رقم {number} جاهز.' UNION ALL SELECT 'pt','O seu pedido está pronto','O pedido #{number} está pronto.' UNION ALL SELECT 'ja','ご注文の準備ができました','注文番号 {number} の準備ができました。'
) x
WHERE t.template_key = 'order_ready'
ON DUPLICATE KEY UPDATE title = VALUES(title), body = VALUES(body);
